"""The Tally reference: one entry per built-in — group, one-line doc, a worked example and its exact result.

Every example is executed by `tally --selftest` (and by `tally describe --verify`): the lines before the last are run,
the last line is evaluated, and its value (as Tally prints it inside a list or map) must equal `result`.
A built-in without an entry fails the selftest, so the reference cannot fall behind the code.

Examples that need data (bank table, native stores) use the real local files; they are marked `data: True`.
"""

GROUPS = ["numbers & money", "dates", "lists", "maps & records", "strings", "output", "files", "data search",
          "reasoning", "quantum simulation", "qubits", "timing qubits", "semantic qubits", "experiments", "ranges", "forensic math", "provenance", "errors & meta"]

PRELUDE = """fact Paid("Customer", $25.00, @2040-02-03) from "DOC_10001"
fact Paid("Customer", $55.00, @2040-02-13) from "DOC_10001"
fact not Disclosed("Customer", "x") from "Synthetic disclosure register"
rule big { when Paid("Customer", m, t), m >= $50.00 => Big(m) }
rule unexplained { when Paid("Customer", m, t) => Unexplained(m) unless Explained(m) }
fact Explained($25.00) from "SMS SYN_10002"
rule told { when Paid("Customer", m, t), not Disclosed("Customer", m) => Untold(m) }
infer()"""

